import { mkdir, readFile, stat, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const packageDir = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  ".."
);
const repoRoot = path.resolve(packageDir, "../..");
const generatedDir = path.join(packageDir, "src/generated");
const generatedHeader =
  "// AUTO-GENERATED at build time for packages/shopstr-mcp/src/generated/. Do not edit this file directly; edit the source file named below and rebuild.\n";

const files = [
  {
    from: "utils/parsers/canonical-product-parser.ts",
    to: "canonical-product-parser.ts",
  },
  {
    from: "utils/parsers/product-tag-helpers.ts",
    to: "product-tag-helpers.ts",
  },
  {
    from: "utils/nostr/canonical-nip05.ts",
    to: "canonical-nip05.ts",
  },
];

await mkdir(generatedDir, { recursive: true });

for (const file of files) {
  const source = path.join(repoRoot, file.from);
  const destination = path.join(generatedDir, file.to);

  try {
    await stat(source);
  } catch (error) {
    throw new Error(`Canonical source file missing: ${source}`, {
      cause: error,
    });
  }

  const sourceContents = await readFile(source, "utf8");
  await writeFile(
    destination,
    `${generatedHeader}// Source: ${file.from}\n${sourceContents}`
  );
}
